from pathlib import Path

import joblib
import pandas as pd
from fastapi import HTTPException

FEATURES = ["attendance", "internal_marks", "assignment_score"]


def load_model(path: Path):
    # Only load artifacts generated by our trusted training command. Pickle/joblib is executable.
    if not path.is_file():
        return None
    artifact = joblib.load(path)
    if artifact.get("features") != FEATURES or artifact.get("schema_version") != 1:
        raise ValueError("Model artifact has an incompatible feature schema")
    return artifact


def predict(artifact, features):
    if artifact is None:
        raise HTTPException(503, "Model unavailable. Run python -m ml.train_model and restart the API.")
    frame = pd.DataFrame([features], columns=FEATURES)
    model = artifact["model"]
    class_index = list(model.classes_).index(1)
    probability = float(model.predict_proba(frame)[0, class_index])
    return {
        "needs_support": probability >= 0.5,
        "support_probability": round(probability, 4),
        "model": artifact["name"],
        "training_data": "synthetic",
        "notice": "Educational demonstration, not validated for real student decisions.",
    }
